    return a // b

def intervals_intersect(a, b):
    """Check if two intervals intersect"""
    return not (b[0] > a[1] or a[0] > b[1])

def interval_intersection(a, b):
    """Get intersection of two intervals"""
    return (max(a[0], b[0]), min(a[1], b[1]))

def interval_union(intervals):
    """Get union of a list of intervals"""
    if not intervals:
        return []
    intervals.sort()
    result = [intervals[0]]
    for i in intervals[1:]:
        if i[0] <= result[-1][1]:
            result[-1] = (result[-1][0], max(result[-1][1], i[1]))
        else:
            result.append(i)
    return result

