    Implement Bleichenbacher's attack
    c0: original ciphertext
    n: modulus
    e: public exponent
    k: byte length of n
    oracle_fn: padding oracle function
    """
    B = 2 ** (8 * (k - 2))
    c = c0
    M = [(2 * B, 3 * B - 1)]
    i = 1
    s = ceildiv(n, 3 * B)

    while len(M) > 0:
        print(f"Step {i}, |M|={len(M)}")
        if i == 1:
            while True:
                if oracle_fn(c * pow(s, e, n) % n, n, e):
                    break
                s += 1
        elif len(M) >= 2:
