                s_max = (3 * B + r * n) // a
                for s_candidate in range(s_min, s_max + 1):
                    if oracle_fn(c * pow(s_candidate, e, n) % n, n, e):
                        s = s_candidate
                        found = True
                        break
                if not found:
                    r += 1

