# Enable logging
context.log_level = 'debug'

class OracleConnection:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.conn = None
        self.n = None
        self.e = None
        self.challenge = None
        self.connect()

    def connect(self):
        if self.conn:
            self.conn.close()
        self.conn = remote(self.host, self.port)
        if not self.n:  # First connection, get parameters
            self.conn.recvuntil(b"Public key (n, e):")
            key_line = self.conn.recvline().decode().strip()
            self.n, self.e = map(int, key_line.split(','))
            self.conn.recvuntil(b"Here's your challenge (hex):")
            self.challenge = int(self.conn.recvline().decode().strip(), 16)

    def query(self, ct):
        try:
            self.conn.sendlineafter(b"Enter your ciphertext (hex):", hex(ct)[2:].encode())
            resp = self.conn.recvline(timeout=5)
            if b"Invalid" in resp:
                return False
            if b"csawctf{" in resp:
                self.flag = resp
            return True
        except Exception as e:
            print(f"Query error: {e}")
            self.connect()
            return self.query(ct)

def pkcs1_v1_5_pad(msg, k):
    return b'\x00\x02' + b'\xff' * (k - 3 - len(msg)) + b'\x00' + msg

def integer_to_bytes(n):
    return n.to_bytes((n.bit_length() + 7) // 8, 'big')

def bytes_to_integer(b):
    return int.from_bytes(b, 'big')

class BleichenbacherOracle:
    def __init__(self, oracle_conn):
        self.oracle = oracle_conn
        self.n = oracle_conn.n
        self.e = oracle_conn.e
        self.k = (self.n.bit_length() + 7) // 8
        self.B = 2 ** (8 * (self.k - 2))
        self.c0 = oracle_conn.challenge

    def check_padding(self, c):
        return self.oracle.query(c)

    def step1(self):
        s = self.n // (3 * self.B)
        while True:
            if self.check_padding((self.c0 * pow(s, self.e, self.n)) % self.n):
                return s
            s += 1

    def step2(self, si):
        si = si + 1
        while True:
            if self.check_padding((self.c0 * pow(si, self.e, self.n)) % self.n):
                return si
            si += 1

    def step3(self, si, intervals):
        a, b = intervals[0]
        ri = 2 * (b * si - 2 * self.B) // self.n
        while True:
            si_start = (2 * self.B + ri * self.n + b - 1) // b
            si_end = (3 * self.B + ri * self.n) // a
            for si in range(si_start, si_end + 1):
                if self.check_padding((self.c0 * pow(si, self.e, self.n)) % self.n):
                    return si
            ri += 1

    def get_intervals(self, si, intervals):
        new_intervals = []
        for a, b in intervals:
            r_min = (a * si - 3 * self.B + 1) // self.n
            r_max = (b * si - 2 * self.B) // self.n
            for r in range(r_min, r_max + 1):
                new_a = max(a, (2 * self.B + r * self.n + si - 1) // si)
                new_b = min(b, (3 * self.B - 1 + r * self.n) // si)
                if new_a <= new_b:
                    new_intervals.append((new_a, new_b))
        return new_intervals

    def merge_intervals(self, intervals):
        if not intervals:
            return []
        intervals.sort()
        result = [intervals[0]]
        for interval in intervals[1:]:
            if interval[0] <= result[-1][1] + 1:
                result[-1] = (result[-1][0], max(result[-1][1], interval[1]))
            else:
                result.append(interval)
        return result

    def attack(self):
        print("[+] Starting Bleichenbacher attack...")

        # Step 1: Blinding
        print("[+] Step 1: Blinding...")
        s0 = self.step1()
        M = [(2 * self.B, 3 * self.B - 1)]
        si = s0
        i = 1

        while True:
            print(f"[+] Round {i}")
            print(f"[+] Number of intervals: {len(M)}")
            print(f"[+] Current intervals: {M}")

            if len(M) == 1 and M[0][0] == M[0][1]:
                return M[0][0]

            if i == 1:
                si = self.step2(si)
            elif len(M) > 1:
                si = self.step2(si)
            else:
                si = self.step3(si, M)

            M = self.merge_intervals(self.get_intervals(si, M))
            i += 1

def main():
    oracle_conn = OracleConnection('nervcenter.moyix.net', 2000)
    print(f"[+] Connected to server")
    print(f"[+] n = {oracle_conn.n}")
    print(f"[+] e = {oracle_conn.e}")
    print(f"[+] challenge = {hex(oracle_conn.challenge)}")

